mapper.select:
SELECT cn.*, c.post_id 
FROM comment_notice cn
LEFT JOIN comment c ON cn.business_id = c.comment_id
WHERE cn.user_id = #{request.userId}

    AND (
    cn.create_time < #{request.lastCreateTime}
    OR (cn.create_time = #{request.lastCreateTime} AND cn.id < #{request.lastId})
    )

ORDER BY cn.create_time DESC, cn.id DESC
LIMIT #{request.pageSize}
